/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: id, track
 *   Constants: publicAlbum, hiddenAlbum, hiddenArtist, publicArtist, visibleTrack, hiddenTrack,
 *              inheritedHidden, visibleStandalone, image, collection, hiddenPlacement, visiblePlacement
 *   Variables: harness, server, origin
 * Tests
 *   - effective visibility filters before pagination and does not mutate management records
 *   - hidden Credit subjects, Track membership, and known Artist IDs do not leak
 *   - Home and source-bound pagination hide one occurrence while retaining another
 *   - hidden known media IDs reject HEAD, Range and legacy redirects before storage disclosure
 *   - legacy metadata edits retain hidden settings while public adapters remain denied
 *   - private Library and history omit hidden metadata before search/pagination but preserve saves
 *   - Playlist hidden members retain removable tombstones without metadata or summary artwork
 * @end-catalog */

import assert from 'node:assert/strict';
import { after, before, test } from 'node:test';
import type { Server } from 'node:http';
import { ObjectId } from 'mongodb';
import { UserLibrary } from '../../src/models/userLibrary';
import { toPlaylistDetail, toPlaylistPage } from '../../src/services/playlists/playlistProjectionService';
import { listListenerLibrary, getListenerRecentlyPlayed } from '../../src/services/listener/listenerContentService';
import { Artist } from '../../src/models/artist';
import { Album } from '../../src/models/album';
import { AudioTrack } from '../../src/models/audioTrack';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { findPublicAudioTracks, findPublicAudioTrackById } from '../../src/services/catalog/catalogVisibilityService';
import { getListenerAlbum, getListenerHome, searchListenerContent } from '../../src/services/listener/listenerContentService';
import { listPublicAudioTracks, getPublicArtist } from '../../src/services/catalog/publicCatalogService';
import { resolvePublicCoverArtAsset } from '../../src/services/image/imageStorageService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness;
let server: Server;
let origin = '';
const id = (value: number) => new ObjectId(value.toString(16).padStart(24, '0'));
const publicAlbum = id(1), hiddenAlbum = id(2), hiddenArtist = id(3), publicArtist = id(4);
const visibleTrack = id(10), hiddenTrack = id(11), inheritedHidden = id(12), visibleStandalone = id(13);
const image = id(20), collection = id(30), hiddenPlacement = id(31), visiblePlacement = id(32);
const track = (_id: ObjectId, title: string, albumId?: string, visibility?: unknown) => ({
    _id, title, albumId, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: _id.toHexString(),
    ...(visibility !== undefined ? { visibility } : {}),
    credits: [{ subjectType: 'artist', subjectId: hiddenArtist.toHexString(), role: 'primary', order: 0 }],
    attributionStatus: 'credited'
});

before(async () => {
    harness = await startMongoReplicaSet('archtree-catalog-visibility-test');
    const db = getDb()!;
    await db.collection('artists').insertMany([
        { _id: hiddenArtist, name: 'Secret subject', lifecycleStatus: 'ready', visibility: 'hidden', coverArtId: image.toHexString() },
        { _id: publicArtist, name: 'Visible subject', lifecycleStatus: 'ready' }
    ]);
    await db.collection('albums').insertMany([
        { _id: publicAlbum, title: 'Visible Album', lifecycleStatus: 'ready', audioTrackIds: [visibleTrack.toHexString(), hiddenTrack.toHexString()] },
        { _id: hiddenAlbum, title: 'Secret Album', lifecycleStatus: 'ready', visibility: 'hidden' }
    ]);
    await db.collection('audioTracks').insertMany([
        track(visibleTrack, 'M visible', publicAlbum.toHexString()),
        track(hiddenTrack, 'A own hidden', publicAlbum.toHexString(), 'hidden'),
        track(inheritedHidden, 'B inherited hidden', hiddenAlbum.toHexString()),
        track(visibleStandalone, 'Z standalone'),
        track(id(14), 'C malformed', undefined, ['public'])
    ]);
    await db.collection('imageAssets').insertOne({ _id: image, ownerType: 'artist', ownerId: hiddenArtist.toHexString(), uploadStatus: 'ready', s3Key: `images/${image}`, contentType: 'image/jpeg' });
    await db.collection('contentCollections').insertOne({ _id: collection, name: 'Shared collection', presentation: 'list', mode: 'manual', contentType: 'audioTrack', items: [{ contentType: 'audioTrack', contentId: visibleTrack.toHexString(), order: 0 }] });
    await db.collection('pages').insertOne({ slug: 'home', title: 'Home', items: [
        { itemId: hiddenPlacement.toHexString(), itemType: 'list', collectionId: collection.toHexString(), visibility: 'hidden', order: 0 },
        { itemId: visiblePlacement.toHexString(), itemType: 'list', collectionId: collection.toHexString(), order: 1 }
    ] });
    const app = createApp();
    server = await new Promise(resolve => { const value = app.listen(0, '127.0.0.1', () => resolve(value)); });
    const address = server.address();
    assert.ok(address && typeof address !== 'string');
    origin = `http://127.0.0.1:${address.port}`;
});
after(async () => {
    await new Promise<void>((resolve, reject) => server?.close(error => error ? reject(error) : resolve()));
    await harness?.stop();
});

test('effective visibility filters before pagination and does not mutate management records', async () => {
    const rows = await findPublicAudioTracks().sort({ title: 1 }).limit(1).toArray();
    assert.deepEqual(rows.map(row => String(row._id)), [visibleTrack.toHexString()]);
    assert.deepEqual((await listPublicAudioTracks(1, 0)).map(row => row._id), [visibleTrack.toHexString()]);
    assert.equal(await findPublicAudioTrackById(inheritedHidden.toHexString()), null);
    assert.equal((await getDb()!.collection('audioTracks').findOne({ _id: inheritedHidden }))?.uploadStatus, 'ready');
});

test('hidden Credit subjects, Track membership, and known Artist IDs do not leak', async () => {
    assert.equal(await getPublicArtist(hiddenArtist.toHexString()), null);
    const album = await getListenerAlbum(publicAlbum.toHexString());
    assert.ok(album);
    const wire = JSON.stringify(album);
    assert.equal(wire.includes(hiddenTrack.toHexString()), false);
    assert.equal(wire.includes(hiddenArtist.toHexString()), false);
    assert.equal(wire.includes('Secret subject'), false);
    const search = await searchListenerContent('hidden');
    assert.equal(search.audioTracks.length, 0);
});

test('Home and source-bound pagination hide one occurrence while retaining another', async () => {
    const home = await getListenerHome();
    assert.deepEqual(home?.sections.map(section => section.id), [visiblePlacement.toHexString()]);
    const hidden = await fetch(`${origin}/api/listener/v1/pages/home/items/${hiddenPlacement}`);
    assert.equal(hidden.status, 404);
    const visible = await fetch(`${origin}/api/listener/v1/pages/home/items/${visiblePlacement}`);
    assert.equal(visible.status, 200);
});

test('hidden known media IDs reject HEAD, Range and legacy redirects before storage disclosure', async () => {
    for (const path of [
        `/content/mediaTrack/stream/${inheritedHidden}`,
        `/content/audioTrack/stream/${hiddenTrack}`,
        `/content/audioTrack/video/${hiddenTrack}`,
        `/content/audioTrack/${hiddenTrack}`,
        `/content/audioTrack/aws/${hiddenTrack}`
    ]) for (const method of ['GET', 'HEAD']) {
        const result = await fetch(`${origin}${path}`, { method, headers: { Range: 'bytes=0-7', 'If-None-Match': '*' }, redirect: 'manual' });
        assert.equal(result.status, 404, `${method} ${path}`);
        assert.equal(result.headers.get('etag'), null);
        assert.equal(result.headers.get('content-range'), null);
        assert.equal(result.headers.get('location'), null);
    }
    assert.equal(await resolvePublicCoverArtAsset(image.toHexString()), null);
    const response = await fetch(`${origin}/content/images/${image}`, { headers: { 'If-None-Match': '*' } });
    assert.equal(response.status, 404);
    const absent = await fetch(`${origin}/content/images/${id(999)}`, { headers: { 'If-None-Match': '*' } });
    assert.equal(response.headers.get('etag'), absent.headers.get('etag'));
    assert.equal(await response.text(), await absent.text());
    for (const path of ['/video', `/video/${id(99)}`]) assert.equal((await fetch(origin + path)).status, 404);
});


test('legacy metadata edits retain hidden settings while public adapters remain denied', async () => {
    await Artist.updateById(hiddenArtist.toHexString(), { bio: 'Administrator correction' });
    await Album.updateById(hiddenAlbum.toHexString(), { title: 'Corrected hidden Album' });
    await AudioTrack.updateById(hiddenTrack.toHexString(), { title: 'Corrected hidden track' });
    for (const [collectionName, _id] of [['artists', hiddenArtist], ['albums', hiddenAlbum], ['audioTracks', hiddenTrack]] as const) {
        assert.equal((await getDb()!.collection(collectionName).findOne({ _id }))?.visibility, 'hidden');
    }
    assert.equal(await getPublicArtist(hiddenArtist.toHexString()), null);
    assert.equal(await findPublicAudioTrackById(hiddenTrack.toHexString()), null);
    await assert.rejects(() => Artist.updateById(hiddenArtist.toHexString(), { visibility: 'public' }), {
        code: 'catalog_visibility_operation_required'
    });
});


test('private Library and history omit hidden metadata before search/pagination but preserve saves', async () => {
    const db = getDb()!;
    const userId = id(200).toHexString();
    await db.collection('users').insertOne({ _id: id(200), role: 'user' });
    await db.collection('audioTracks').insertOne({ ...track(id(201), 'Unavailable public audio'), uploadStatus: 'failed' });
    const savedIds = [hiddenTrack, inheritedHidden, visibleTrack, id(201)];
    await db.collection('userSaves').insertMany(savedIds.map((_id, index) => ({
        userId, contentType: 'audioTrack', contentId: _id.toHexString(),
        savedAt: new Date(10_000 - index), lastActivityAt: new Date(10_000 - index)
    })));
    await db.collection('userSaves').insertOne({ userId, contentType: 'album', contentId: hiddenAlbum.toHexString(), savedAt: new Date(20_000) });
    await db.collection('userActivity').insertOne({ userId, recentlyPlayed: savedIds.map(_id => ({ contentType: 'audioTrack', contentId: _id.toHexString(), occurredAt: new Date() })) });
    const first = await listListenerLibrary(userId, { limit: 1 });
    assert.deepEqual(first.items.map(item => item.contentId), [visibleTrack.toHexString()]);
    const all = await listListenerLibrary(userId, { limit: 100 });
    assert.deepEqual(all.items.map(item => item.contentId), [visibleTrack.toHexString(), id(201).toHexString()]);
    const unavailable = all.items[1] as any;
    assert.equal(unavailable.audioTrack.title, 'Unavailable public audio');
    assert.equal(unavailable.audioTrack.available, false);
    assert.equal(unavailable.audioTrack.streamUrl, null);
    assert.equal(JSON.stringify(all).includes('Secret subject'), false);
    assert.deepEqual((await UserLibrary.list(userId, { query: 'hidden' })).items, []);
    assert.equal((await getListenerRecentlyPlayed(userId)).items.length, 1);
    assert.equal((await UserLibrary.statuses(userId, [{ contentType: 'audioTrack', contentId: hiddenTrack.toHexString() }]))[0].saved, true);
    assert.equal(await db.collection('userSaves').countDocuments({ userId }), 5);
    assert.deepEqual((await UserLibrary.list(id(202).toHexString())).items, []);
    for (const hidden of [hiddenTrack, inheritedHidden]) {
        await assert.rejects(() => UserLibrary.save(userId, 'audioTrack', hidden.toHexString()), { statusCode: 404 });
        await assert.rejects(() => UserLibrary.recordPlayed(userId, 'audioTrack', hidden.toHexString()), { statusCode: 404 });
    }
    await UserLibrary.unsave(userId, 'audioTrack', hiddenTrack.toHexString());
    assert.equal((await UserLibrary.statuses(userId, [{ contentType: 'audioTrack', contentId: hiddenTrack.toHexString() }]))[0].saved, false);
    assert.equal(await db.collection('audioTracks').countDocuments({ _id: hiddenTrack }), 1);
});

test('Playlist hidden members retain removable tombstones without metadata or summary artwork', async () => {
    const db = getDb()!;
    await db.collection('audioTracks').updateOne({ _id: hiddenTrack }, { $set: { coverArtUrl: '/private-cover.jpg' } });
    await db.collection('audioTracks').updateOne({ _id: visibleTrack }, { $set: { coverArtUrl: '/public-cover.jpg' } });
    const now = new Date();
    const playlist = { _id: id(210), ownerUserId: id(200).toHexString(), name: 'Owned playlist', revision: 1,
        createdAt: now, updatedAt: now, items: [hiddenTrack, inheritedHidden, visibleTrack].map((_id, index) => ({ itemId: String(index), audioTrackId: _id.toHexString(), addedAt: now })) };
    const detail = await toPlaylistDetail(playlist);
    assert.deepEqual(detail.items.map(item => item.availability), ['unavailable', 'unavailable', 'ready']);
    assert.equal(detail.items[0].audioTrack, null);
    assert.equal(detail.items[0].audioTrackId, hiddenTrack.toHexString());
    assert.equal(detail.artworkUrl, '/public-cover.jpg');
    assert.equal(JSON.stringify(detail).includes('private-cover'), false);
    const summary = await toPlaylistPage({ records: [{ ...playlist, itemCount: 3, artworkAudioTrackIds: playlist.items.map(item => item.audioTrackId) }], nextCursor: null });
    assert.equal(summary.items[0].artworkUrl, '/public-cover.jpg');
    assert.equal(summary.items[0].itemCount, 3);
});
